package tn.esprit.partnerintelligence.entity;
import jakarta.persistence.*;import java.time.Instant;@Entity public class AnomalyAlert { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long partnerId; private String anomalyType; private Double severityScore; @Column(length=1000) private String explanation; private String status="OPEN"; private Instant createdAt=Instant.now(); public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getPartnerId(){return partnerId;} public void setPartnerId(Long partnerId){this.partnerId=partnerId;} public String getAnomalyType(){return anomalyType;} public void setAnomalyType(String anomalyType){this.anomalyType=anomalyType;} public Double getSeverityScore(){return severityScore;} public void setSeverityScore(Double severityScore){this.severityScore=severityScore;} public String getExplanation(){return explanation;} public void setExplanation(String explanation){this.explanation=explanation;} public String getStatus(){return status;} public void setStatus(String status){this.status=status;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant createdAt){this.createdAt=createdAt;} }